from test_group_scopes import tests,raid
from test_bufftap import test
from test_blessings import setup

test('Uniform party blessing overrides class and player choices',setup+"BuffTap:SetBlessingPlayer({unit='party1'},'bow',false); BuffTap:SetBlessingPlanMode('Party',0,'same','bok'); assert(BuffTap:BlessingChoice({unit='party1',class='WARRIOR',group=1})=='bok'); assert(BuffTap:BlessingChoice({unit='party2',class='PRIEST',group=1})=='bok')")
test('Switching back to class mode restores saved exceptions',setup+"BuffTap:SetBlessingPlayer({unit='party1'},'bow',false); BuffTap:SetBlessingPlanMode('Party',0,'same','bok'); BuffTap:SetBlessingPlanMode('Party',0,'class'); assert(BuffTap:BlessingChoice({unit='party1',class='WARRIOR',group=1})=='bow' and BuffTap.db.blessingClasses.PRIEST=='bow')")
test('Uniform unlearned choice does not substitute another blessing',setup+"spells[20217].known=false; BuffTap:SetBlessingPlanMode('Party',0,'same','bok'); refresh(); assert(not BuffTap.action)")
test('Uniform class-wide safety still blocks excluded raid classes',raid+"BuffTap:SetBlessingPlanMode('Raid',2,'same','bok'); BuffTap:SetBlessingPlanMode('Raid',3,'same','bok'); BuffTap.db.raidGroups[3]=false; refresh(); assert(BuffTap.action and not BuffTap.action.groupCast and BuffTap.action.key=='bok')")
test('Uniform mode does not bypass Never Salvation',setup+"BuffTap:SetBlessingPlanMode('Party',0,'same','bok'); BuffTap:SetBlessingPlayer({unit='party1'},'bow',true); assert(not BuffTap:SalvationRecipientAllowed({unit='party1',class='WARRIOR',group=1})); assert(BuffTap:BlessingChoice({unit='party1',class='WARRIOR',group=1})=='bok')")
test('Salvation is rejected as a uniform blessing',setup+"assert(not BuffTap:SetBlessingPlanMode('Party',0,'same','bos')); assert(BuffTap.db.blessingPartyMode~='same')")
test('Party and raid class settings do not share tables',setup+"BuffTap:SetGroupBlessingSettings('WARRIOR',0,'bok',nil,false,'Raid'); assert(BuffTap.db.blessingClasses.WARRIOR=='bom'); BuffTap:SetGroupBlessingSettings('WARRIOR',0,'bow',nil,false,'Party'); assert(BuffTap.db.blessingRaidDefaults.classes.WARRIOR=='bok')")
test('Party and raid uniform settings remain independent',setup+"BuffTap:SetBlessingPlanMode('Party',0,'same','bow'); BuffTap:SetBlessingPlanMode('Raid',0,'same','bok'); assert(BuffTap:BlessingPlan('Party',0).blessing=='bow' and BuffTap:BlessingPlan('Raid',0).blessing=='bok')")
test('Raid subgroup uniform selection wins over player exception',raid+"BuffTap:SetBlessingPlayer({unit='raid2'},'bow',false); BuffTap:SetBlessingPlanMode('Raid',2,'same','bok'); assert(BuffTap:BlessingChoice({unit='raid2',class='WARRIOR',group=2})=='bok')")
test('Raid subgroup class mode overrides uniform raid defaults',raid+"BuffTap:SetBlessingPlanMode('Raid',0,'same','bok'); BuffTap:SetBlessingPlanMode('Raid',2,'class'); BuffTap:SetGroupBlessingSettings('WARRIOR',2,'bow',nil,false,'Raid'); assert(BuffTap:BlessingChoice({unit='raid2',class='WARRIOR',group=2})=='bow' and BuffTap:BlessingChoice({unit='raid3',class='WARRIOR',group=3})=='bok')")
test('Removing subgroup override restores uniform defaults',raid+"BuffTap:SetBlessingPlanMode('Raid',0,'same','bok'); BuffTap:SetBlessingPlanMode('Raid',2,'same','bow'); BuffTap:ResetBlessingScope(2); assert(BuffTap:BlessingChoice({unit='raid2',class='WARRIOR',group=2})=='bok')")
test('Changing a prepared uniform choice cancels click action',setup+"BuffTap:SetBlessingPlanMode('Party',0,'same','bok'); refresh(); assert(BuffTap.action.key=='bok'); BuffTap:SetBlessingPlanMode('Party',0,'same','bow'); BuffTap.button.scripts.PreClick(nil,'LeftButton',true); assert(not BuffTap.action)")
test('Raid planning view never changes active party casting',setup+"BuffTap:Options(); local f=BuffTap.options; f.raidView.scripts.OnClick(); BuffTap:SetBlessingPlanMode('Raid',0,'same','bok'); refresh(); assert(BuffTap.action.key=='bom' and BuffTap:BlessingContext()=='Party')")
test('Party session exceptions do not leak into raid',setup+"BuffTap:SetBlessingPlayer({unit='party1'},'bow',false,'Party'); assert(BuffTap:GetBlessingPlayer(UnitGUID('party1'),'Party').choice=='bow' and BuffTap:GetBlessingPlayer(UnitGUID('party1'),'Raid').choice==nil)")
test('Raid session exception does not replace party session exception',setup+"BuffTap:SetBlessingPlayer({unit='party1'},'bow',false,'Party'); BuffTap:SetBlessingPlayer({unit='party1'},'bok',false,'Raid'); assert(BuffTap:GetBlessingPlayer(UnitGUID('party1'),'Party').choice=='bow' and BuffTap:GetBlessingPlayer(UnitGUID('party1'),'Raid').choice=='bok')")
test('Copy party into raid deep copies lists and retains subgroup overrides',setup+"BuffTap.db.blessingClasses.WARRIOR='priority'; BuffTap.db.groupBlessingPriorities.WARRIOR={'bom','bow'}; BuffTap:SetBlessingPlanMode('Raid',3,'same','bok'); BuffTap:CopyPartyBlessingsToRaid(); BuffTap.db.groupBlessingPriorities.WARRIOR[1]='bok'; assert(BuffTap.db.blessingRaidDefaults.priorities.WARRIOR[1]=='bom' and BuffTap.db.blessingGroupOverrides[3].blessing=='bok')")
test('Migration retains prior G1 party choice and original raid defaults',setup+"BuffTap.db.blessingRaidDefaults=nil; BuffTap.db.blessingClasses.WARRIOR='bom'; BuffTap.db.blessingGroupOverrides[1]={classes={WARRIOR='bow'},priorities={WARRIOR={'bow','bom'}}}; BuffTap:InitDB(); assert(BuffTap.db.blessingClasses.WARRIOR=='bow' and BuffTap.db.blessingRaidDefaults.classes.WARRIOR=='bom'); BuffTap.db.blessingClasses.WARRIOR='bok'; BuffTap:InitDB(); assert(BuffTap.db.blessingClasses.WARRIOR=='bok')")
test('Malformed plan fields normalize to valid safe class mode',setup+"BuffTap.db.blessingPartyMode={}; BuffTap.db.blessingPartyUniform='bos'; BuffTap.db.blessingRaidDefaults={classes='bad',priorities='bad',mode='bad',blessing='bos'}; BuffTap:InitDB(); assert(BuffTap.db.blessingPartyMode=='class' and BuffTap.db.blessingPartyUniform=='bok' and type(BuffTap.db.blessingRaidDefaults.classes)=='table' and BuffTap.db.blessingRaidDefaults.mode=='class')")
test('Combat blocks mode, copy and reset changes',setup+"combat=true; assert(not BuffTap:SetBlessingPlanMode('Party',0,'same','bok') and not BuffTap:CopyPartyBlessingsToRaid() and not BuffTap:ResetBlessingScope(1)); assert(BuffTap.db.blessingPartyMode~='same')")
test('Party setup opens before raid and uniform hides all exceptions',setup+"BuffTap:Options(); local f=BuffTap.options; assert(f.blessingContext=='Party' and f.blessingRows[1].shown); f.blessingSame.scripts.OnClick(); assert(f.blessingUniform.shown and not f.blessingRows[1].shown and not f.blessingDetail.shown); f.blessingRows[1].players.scripts.OnClick(); assert(not f.expandedBlessing)")
test('Uniform picker offers only the four blessing families',setup+"BuffTap:Options(); local f=BuffTap.options; f.blessingSame.scripts.OnClick(); f.blessingUniform.scripts.OnClick(f.blessingUniform); assert(#f.blessingMenu.rows==4); for _,r in ipairs(f.blessingMenu.rows) do assert(r.key~='inherit' and r.key~='bos' and r.key~='skip') end")
test('Raid controls are hidden from the party setup',setup+"BuffTap:Options(); local f=BuffTap.options; assert(not f.blessingScopeButtons[1].shown and not f.blessingInherit.shown and not f.copyPartyBlessings.shown); f.raidView.scripts.OnClick(); assert(f.blessingScopeButtons[9].shown and f.copyPartyBlessings.shown)")
test('Party and raid preplanning does not require group membership',setup+"GetNumSubgroupMembers=function() return 0 end; BuffTap.db.group=false; BuffTap:InvalidateRoster(); BuffTap:Options(); local f=BuffTap.options; f.blessingSame.scripts.OnClick(); assert(BuffTap.db.blessingPartyMode=='same'); f.raidView.scripts.OnClick(); f.blessingScopeButtons[4].scripts.OnClick(); f.blessingSame.scripts.OnClick(); assert(BuffTap.db.blessingGroupOverrides[3].mode=='same' and not BuffTap.db.group)")
test('Same-class optional profile copy includes separate plans',setup+"BuffTap:SetBlessingPlanMode('Party',0,'same','bow'); BuffTap:SetBlessingPlanMode('Raid',3,'same','bok'); local source=BuffTap.profileDB:GetCurrentProfile(); BuffTap:CreateSettingsProfile('Dest',true); BuffTap:SetBlessingPlanMode('Party',0,'same','bom'); BuffTap:SetBlessingPlanMode('Raid',3,'same','bol'); assert(BuffTap:CopySettingsProfile(source,BuffTap.profileDB.keys.char)); assert(BuffTap.db.blessingPartyUniform=='bow' and BuffTap.db.blessingGroupOverrides[3].blessing=='bok'); BuffTap.db.blessingGroupOverrides[3].blessing='bow'; assert(BuffTap.profileDB.global.characterSetups[source][BuffTap.profileDB.keys.char].settings.blessingGroupOverrides[3].blessing=='bok')")
test('Shared-only profile copy leaves both blessing plans intact',setup+"local source=BuffTap.profileDB:GetCurrentProfile(); BuffTap:CreateSettingsProfile('Dest',true); BuffTap:SetBlessingPlanMode('Party',0,'same','bow'); BuffTap:SetBlessingPlanMode('Raid',0,'same','bok'); assert(BuffTap:CopySettingsProfile(source)); assert(BuffTap.db.blessingPartyUniform=='bow' and BuffTap.db.blessingRaidDefaults.blessing=='bok')")
test('Cross-class copy cannot import Paladin plans',setup+"local source=BuffTap.profileDB:GetCurrentProfile(); BuffTap:SetBlessingPlanMode('Party',0,'same','bow'); BuffTap:CreateSettingsProfile('Dest',true); classes.player='DRUID'; BuffTap.db.size=80; assert(not BuffTap:CopySettingsProfile(source,BuffTap.profileDB.keys.char)); assert(BuffTap.db.size==80)")
test('Profile rename preserves plan copy sources',setup+"BuffTap:SetBlessingPlanMode('Raid',0,'same','bow'); assert(BuffTap:RenameSettingsProfile('Plan Profile')); local saved=BuffTap.profileDB.global.characterSetups['Plan Profile'][BuffTap.profileDB.keys.char]; assert(saved.settings.blessingRaidDefaults.blessing=='bow' and saved.profile=='Plan Profile')")
test('Reset shared profile keeps character party and raid plans',setup+"BuffTap:SetBlessingPlanMode('Party',0,'same','bow'); BuffTap:SetBlessingPlanMode('Raid',0,'same','bok'); BuffTap:ResetSettingsProfile(); assert(BuffTap.db.blessingPartyUniform=='bow' and BuffTap.db.blessingRaidDefaults.blessing=='bok')")
test('Copying an older same-class profile migrates both plans',setup+"local source=BuffTap.profileDB:GetCurrentProfile(); BuffTap:CreateSettingsProfile('Dest',true); BuffTap.profileDB.global.characterSetups[source].Older={class='PALADIN',profile=source,settings={blessingClasses={WARRIOR='bow'},groupBlessingPriorities={},blessingGroupOverrides={}}}; assert(BuffTap:CopySettingsProfile(source,'Older')); assert(BuffTap.db.blessingClasses.WARRIOR=='bow' and BuffTap.db.blessingRaidDefaults.classes.WARRIOR=='bow')")
test('Salvation player exclusions remain editable in uniform mode',setup+"BuffTap:SetBlessingPlanMode('Party',0,'same','bok'); BuffTap:Options(); local f=BuffTap.options; f.salvationRecipients.scripts.OnClick(); f.salvationPanel.playerExclusions.scripts.OnClick(); assert(f.blessingDetail.shown and f.expandedBlessing=='SALVATION' and not f.blessingPlayerRows[1].pick.shown); local c=f.blessingPlayerRows[1].protect; c:SetChecked(true); c.scripts.OnClick(c); assert(not BuffTap:SalvationRecipientAllowed(f.blessingPlayerRows[1].entry)); assert(BuffTap.db.blessingPartyMode=='same')")
test('Older subgroup class override survives uniform raid defaults',raid+"BuffTap.db.blessingGroupOverrides[2]={classes={WARRIOR='bow'},priorities={}}; BuffTap:SetBlessingPlanMode('Raid',0,'same','bok'); assert(BuffTap:BlessingChoice({unit='raid2',class='WARRIOR',group=2})=='bow')")
test('Follow Buffs settings preserves both saved plans',setup+"BuffTap:SetBlessingPlanMode('Party',0,'same','bok'); BuffTap:SetBlessingPlanMode('Raid',3,'same','bow'); BuffTap:Options(); local f=BuffTap.options; f.followBuffSettings.scripts.OnClick(); assert(not BuffTap.db.blessingAssignments and BuffTap.db.blessingPartyUniform=='bok' and BuffTap.db.blessingGroupOverrides[3].blessing=='bow'); f.blessingByClass.scripts.OnClick(); assert(BuffTap.db.blessingAssignments and BuffTap.db.blessingPartyMode=='class')")
test('Raid class rows fit above the Salvation separator',setup+'''
local original=CreateFrame
CreateFrame=function(...)
 local frame=original(...); local size=frame.SetSize
 frame.SetSize=function(self,w,h) self.width=w; self.height=h; size(self,w,h) end
 frame.SetPoint=function(self,...) local p={...}; if p[1]=="TOPLEFT" then self.points=p end end
 return frame
end
BuffTap:Options(); local f=BuffTap.options; f.raidView.scripts.OnClick()
for _,row in ipairs(f.blessingRows) do assert(-row.points[3]+row.height<=500) end
assert(f.height==868 and #f.blessingScopeButtons==9)
''')
test('Shared profile switching never replaces character plans',setup+"local original=BuffTap.profileDB:GetCurrentProfile(); BuffTap:CreateSettingsProfile('Other',true); BuffTap:SetBlessingPlanMode('Party',0,'same','bow'); BuffTap:SetBlessingPlanMode('Raid',0,'same','bok'); assert(BuffTap:SelectSettingsProfile(original)); assert(BuffTap.db.blessingPartyUniform=='bow' and BuffTap.db.blessingRaidDefaults.blessing=='bok')")
test('Inherited class preview respects explicit recipient filter overrides',setup+"BuffTap.db.blessingClasses.PRIEST=nil; BuffTap.db.buffs.bok=false; BuffTap.db.buffs.bow=false; BuffTap.db.buffs.bom=true; BuffTap.db.buffClasses.bom={PRIEST=true}; BuffTap:Options(); assert(BuffTap.options.blessingRows[5].pick.text:find('Might')); assert(BuffTap:BlessingChoice({unit='party2',class='PRIEST',group=1})=='bom')")
test('Paladin Groups cannot expose the obsolete assignment page',setup+"BuffTap:Options(); local f=BuffTap.options; f.blessingLegacy=true; BuffTap:Options(); assert(f.blessingPanel.shown and not f.legacyGroups.shown and not f.backBlessings)")
test('Independent Salvation controls remain available without legacy navigation',setup+"BuffTap:Options(); local f=BuffTap.options; f.salvationRecipients.scripts.OnClick(); assert(f.salvationPanel.shown and #f.salvationPanel.groups==8 and f.salvationPanel.playerExclusions); assert(f.blessingCasting and f.followBuffSettings)")
print('ALL',len(tests),'SCENARIOS PASSED')
